</head>
<body>
<header>
  <h1>Voxel Sandbox</h1>
  <div class="hud">
    <div id="world">8x8x8</div>
    <div id="position">1,1,1</div>
    <div id="facing">east</div>
    <div id="status">Ready</div>
  </div>
  <div class="controls">
    <button id="turn-left">Turn Left</button>
    <button id="turn-right">Turn Right</button>
  </div>
</header>
<main>
  <div id="scene"></div>
</main>
<script src="world.js"></script>
<script src="app.js"></script>
</body>
</html>
