h1{font-size:18px;margin:0 16px 0 0}
.hud{display:flex;gap:10px;flex-wrap:wrap}
.hud>div{background:#1e2430;border:1px solid #3a4356;border-radius:6px;padding:6px 10px;font-size:13px}
