.controls{margin-left:auto;display:flex;gap:8px}
button{background:#3a4356;color:#e8ecf1;border:1px solid #4a5570;border-radius:6px;padding:8px 14px;font-size:14px;cursor:pointer}
button:hover{background:#4a5570}
button:active{transform:translateY(1px)}
